// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EBU} from "../src/EBU.sol";

contract InvMutTest is Test {
    EBU c;
    function setUp() public { c = new EBU(); }

    // fuzzed parameters: an address `from` and an arbitrary bytes blob `data`
    // we will craft empty recipients and pass data to v (length mismatch not allowed by Solidity when constructing arrays),
    // so we only need to fuzz `from` and a dummy uint to ensure generality.
    function testFuzz_property(address from, uint256 dummy) public {
        // Keep the domain wide: allow any from (including zero).
        // The property we check targets the empty _tos array case explicitly, which the reference rejects.

        address caddress = address(0xBEEF);

        // Prepare empty recipients and values arrays
        address[] memory tos = new address[](0);
        uint[] memory vals = new uint[](0);

        // Call and observe whether it reverts. The reference MUST revert for empty _tos;
        // the mutant will allow it and return true for some inputs.
        bool ok;
        try c.transfer(from, caddress, tos, vals) {
            ok = true;
        } catch {
            ok = false;
        }

        // Assert that the call reverted (ok == false). This holds for the reference for ALL inputs,
        // and the mutant violates it for some fuzzed inputs (it returns true instead of reverting).
        assertTrue(!ok);
    }
}
